       $len1 = strlen($word1) + 1;
       $len2 = strlen($word2) + 1;
       $matrix = [];

       for ($i = 0; $i <= $len1; $i++) {
           $matrix[$i][] = $i;
       }

       for ($j = 0; $j <= $len2; $j++) {
           $matrix[0][] = $j;
       }

